{
  "meta": {
    "sourceEnv": "partial.to (staging)",
    "regionsNote": "Workload regions — prod: us-east-2, eu-central-1 · staging: us-west-2, us-east-2, eu-west-1. The overview shows the intended prod shape; the per-service views use staging cluster names."
  },
  "views": [
    {
      "id": "overview",
      "title": "Logical overview",
      "intro": "The shape of the platform: every region is identical and split into M cells. Each cell is an EKS cluster (Entire API, Search, entire-core) with its own EntireDB + PgSQL. Object Store is regional — shared by all cells; CockroachDB is global, replicated across regions. The CLI hits a cell's Entire API directly; the browser goes via the Cloudflare Web BFF. Both ask entire-core where each repo + account lives. Click Entire API, Search, entire-core or EntireDB to drill in."
    },
    {
      "id": "entire-api",
      "title": "Entire API",
      "repo": "https://github.com/entirehq/entire-api",
      "intro": "Entire API — the serving plane + API gateway (one image, three binaries). The api server reads the repo/user Postgres stores, authorizes via a regional SpiceDB replica, verifies JWTs against entire-core, and reverse-proxies EntireDB's git plane. The repo-activity and user-activity workers turn EntireDB ref events into activity, forwarding residency-safe metadata cross-region over NATS."
    },
    {
      "id": "search-ingestion",
      "title": "Search · sessions",
      "repo": "https://github.com/entirehq/entire-search",
      "intro": "Semantic search over sessions / checkpoints / transcripts (entire-search). The indexer consumes ref events, fetches transcripts via go-git-api, embeds with Cohere into Turbopuffer; repo/ACL metadata lives in PlanetScale. Queries are served at the Cloudflare edge (with a k8s query service as the migration target). A parallel Cloudflare-Queue path indexes from R2 transcripts."
    },
    {
      "id": "peregrine",
      "title": "Search · code",
      "repo": "https://github.com/entirehq/peregrine",
      "intro": "Code search (peregrine) — lexical/structural, not semantic. peregrine-index consumes ref events, git-fetches source, and builds trigram/ngram + tree-sitter symbol indexes (.pg files) into S3; peregrine-query serves text/symbol/go-to-definition from an LRU cache of those .pg files, enforcing per-repo ACLs via SpiceDB. S3 is the index handoff; NATS carries cache invalidation."
    },
    {
      "id": "entire-core",
      "title": "entire-core",
      "repo": "https://github.com/entirehq/entiredb/tree/main/cmd/entire-core",
      "intro": "The control plane — global identity/resource records + per-jurisdiction regional auth (OAuth, JWT minting, STS token exchange, SpiceDB authorization, PII). Global vs regional is a CockroachDB split, not an HTTP hop: regional pods hold both DSNs. SpiceDB runs as a sidecar in regional pods; workos-poller and an hourly permsreconciler keep org/permission data fresh."
    },
    {
      "id": "entiredb",
      "title": "EntireDB",
      "repo": "https://github.com/entirehq/entiredb",
      "intro": "The distributed git object store (data plane) — entire-server, a DHT-sharded, consensus-free peer-to-peer cluster on EC2, one per cell. Objects live in BadgerDB on per-node EBS (quorum writes across AZs, async repair); refs + metadata in Postgres. Clients use git-remote-entire; services read via go-git-api; backups stream git bundles to S3."
    },
    {
      "id": "mirror-pipeline",
      "title": "Mirror pipeline",
      "repo": "https://github.com/entirehq/mirror-pipeline",
      "intro": "GitHub webhooks → webhook-ingest → fanout (placement resolved via entire-core) → per-cell mirror_git_v1 → mirror-worker git-syncs repos into EntireDB. webhook-forwarder mirrors raw webhooks to the Cloudflare web app; failures are recorded in a NATS KV and re-kicked hourly. (The old mirror_perms_v1 path is retired — entire-core-global now consumes webhooks directly.)"
    },
    {
      "id": "permissions",
      "title": "Permissions",
      "repo": "https://github.com/entirehq/entiredb/tree/main/core/api",
      "intro": "How access is decided for orgs, projects, repos, and GitHub mirrors. A mirror is promoted to a native repo (its /gh/owner/repo URL preserved) and governed by SpiceDB like anything else. Org-owned upstreams lazily create a system-managed gh:<id> org with no human members; user-owned ones hang off the creator's account. Mirror access is explicit — the creator is seeded, teammates are added by an admin API — and is deliberately never synced from GitHub collaborators or org membership. Mutating needs a live GitHub admin check; pull/push is pure SpiceDB."
    },
    {
      "id": "spicedb-authz",
      "title": "SpiceDB authz",
      "repo": "https://github.com/entirehq/entiredb/tree/main/core/authz",
      "intro": "The Zanzibar-style authorization schema entire-core writes into SpiceDB — the single source of truth for every access decision. Five resource definitions (platform, org, team, project, repo) plus one unified account subject; permissions are computed unions that cascade repo→project→org with a platform escape hatch. The deliberate twist: manage is decoupled from read/write at every level, so owning an org or repo never implies the right to pull or push without an explicit grant."
    },
    {
      "id": "nats",
      "title": "NATS messaging",
      "repo": "https://github.com/entirehq/fleet/tree/main/apps/nats-streams",
      "intro": "The NATS JetStream backbone, end to end: every stream and KV bucket on the bus with its producers, consumers, and message types. EntireDB publishes ref changes onto repo_refs_v1 (a replayable Limits bus four services consume independently); WorkQueues carry git-sync, repo-indexing, analysis and repo-ops jobs; and residency-safe activity + GitHub metadata move cross-region by publishing directly into the destination cell's island. Each region is its own island — no supercluster �
---GLOSSARY---
{
  "limits-stream": {
    "label": "Limits stream",
    "def": "JetStream retention where messages are kept until a size/age/count limit, then aged out (discard=old evicts the oldest). A replayable bus — multiple consumers can re-read; unlike WorkQueue, an ack doesn't remove the message."
  },
  "core-nats": {
    "label": "Core NATS",
    "def": "Plain NATS pub/sub without JetStream — fire-and-forget, no persistence, no durable consumer, no replay. Used for cheap ephemeral signals like peregrine's cache-invalidation broadcast."
  },
  "nack": {
    "label": "nack (JetStream controller)",
    "def": "The NATS Kubernetes controller that reconciles Stream / Consumer / KeyValue custom resources. Lets streams be declared in fleet (GitOps) instead of created imperatively at process startup."
  },
  "ref-event": {
    "label": "RefEvent",
    "def": "The JSON notification published on repo_refs_v1 when a git ref changes (repo, ref, op, old/new target). A non-authoritative projection of the signed RSL log entry; consumers refetch the tamper-evident record by (repo, sequence)."
  },
  "consensus-free": {
    "label": "Consensus-free",
    "def": "No Raft/Paxos. Correctness comes from content-addressed (immutable) objects + quorum replication + Postgres compare-and-swap on refs."
  },
  "dht": {
    "label": "DHT",
    "def": "Distributed hash table — a decentralized key→nodes lookup. EntireDB maps each repoID to the set of nodes currently storing it."
  },
  "kademlia": {
    "label": "Kademlia",
    "def": "The DHT algorithm EntireDB uses: 32-byte node/key ids, XOR distance metric, parallel lookups converging on the K-closest nodes."
  },
  "content-addressed": {
    "label": "Content-addressed",
    "def": "An object's key is the hash of its bytes, so it is immutable by definition and safe to deduplicate or replicate without conflict."
  },
  "quorum": {
    "label": "Quorum",
    "def": "The minimum number of independent providers that must hold an object before a write counts. EntireDB fans to K-closest across ≥2 AZs."
  },
  "az": {
    "label": "Availability Zone",
    "def": "An isolated datacenter within an AWS region. Replicas are spread across distinct AZs so one AZ failure can't make a repo unavailable."
  },
  "cas": {
    "label": "Compare-and-swap",
    "def": "An atomic update that only succeeds if the current value matches an expected value. Used for every ref update — no distributed lock."
  },
  "packfile": {
    "label": "Packfile",
    "def": "Git's delta-compressed binary bundle of many objects. Large pushes are stored as .pack/.idx on EBS and periodically repacked."
  },
  "rsl": {
    "label": "RSL (Reference State Log)",
    "def": "A gittuf-compatible, append-only chain of signed commits recording every ref change — a tamper-evident, externally verifiable audit trail."
  },
  "provider-record": {
    "label": "Provider record",
    "def": "A DHT entry advertising that a node holds a given repoID. TTL 24h, re-announced at 23h, evicted when the node leaves."
  },
  "badgerdb": {
    "label": "BadgerDB",
    "def": "An embedded LSM key-value store used per-node for loose git objects and repo-tracking markers."
  },
  "diss": {
    "label": "DISS",
    "def": "Distributed Immutable Storage System — EntireDB's peer-to-peer layer that moves objects between nodes over gRPC."
  },
  "smart-http": {
    "label": "git smart-HTTP",
    "def": "Git's HTTP transport: info/refs discovery + POST git-upload-pack / git-receive-pack for negotiated, delta-compressed exchange."
  },
  "git-remote-entire": {
    "label": "EntireDB / git-remote-entire",
    "def": "EntireDB is the distributed git object store; git-remote-entire is its git remote helper (entire:// URLs) handling auth, discovery, and failover."
  },
  "jwt": {
    "label": "JWT",
    "def": "A signed, self-contained credential. entire-core mints Ed25519 JWTs (sub, aud, scope, exp) carrying no PII and no permissions."
  },
  "jwks": {
    "label": "JWKS",
    "def": "JSON Web Key Set — entire-core's public-key endpoint. Relying parties fetch and cache it to verify JWTs offline, with no per-request callback."
  },
  "sts": {
    "label": "STS (token exchange)",
    "def": "entire-core's /oauth/token security-token service — exchanges a login JWT for short-lived, repo-scoped tokens and GitHub App tokens."
  },
  "rfc8693": {
    "label": "RFC 8693",
    "def": "OAuth 2.0 Token Exchange: grant_type=token-exchange with a subject_token, requested_token_type, audience, and scope."
  },
  "spicedb": {
    "label": "SpiceDB",
    "def": "A Zanzibar-style authorization engine storing relationship tuples and answering permission checks by graph walk; runs as a regional sidecar."
  },
  "relation-tuple": {
    "label": "Relation tuple",
    "def": "A resource:id#relation@subject:id triple in SpiceDB (e.g. repo:r1#push@user:u1); checks walk the graph up the org→project→repo cascade."
  },
  "jurisdiction": {
    "label": "Jurisdiction / residency",
    "def": "A named region (us, eu, au). An account's PII is pinned to its home jurisdiction; content never crosses regions — only residency-safe metadata."
  },
  "cockroachdb": {
    "label": "CockroachDB",
    "def": "Distributed SQL backing entire-core: a global pool (identity, resources, placement, SpiceDB tuples) + a per-jurisdiction regional pool (PII)."
  },
  "lookupbymirror": {
    "label": "LookupByMirror",
    "def": "entire-core's Connect-RPC resolving (provider, owner, repo) → cluster placement — the routing primitive for webhook fan-out."
  },
  "embedding": {
    "label": "Embedding",
    "def": "A dense float vector for a piece of text (Cohere embed-v4.0, 1536-dim); semantically similar texts land close together."
  },
  "ann": {
    "label": "ANN (vector search)",
    "def": "Approximate Nearest Neighbor search over embeddings — finds the closest vectors to a query, even without exact keyword overlap."
  },
  "bm25": {
    "label": "BM25",
    "def": "A classic TF-IDF full-text scoring function. Rewards documents where query terms appear often relative to length."
  },
  "hybrid-search": {
    "label": "Hybrid search",
    "def": "Running BM25 and ANN against the same index in parallel, then merging — capturing both keyword and semantic matches."
  },
  "reranking": {
    "label": "Reranking",
    "def": "A second-pass cross-encoder (Cohere rerank) that reads the query and each candidate together to re-score relevance."
  },
  "turbopuffer": {
    "label": "Turbopuffer",
    "def": "A cloud vector DB that serves both ANN and BM25 from the same namespace via an HTTP/JSON API."
  },
  "namespace": {
    "label": "Namespace",
    "def": "A Turbopuffer isolation unit. v3 = one per org (checkpoints-v3-org-…); v4 = one per repo (v4-<repoULID>)."
  },
  "chunk": {
    "label": "Chunk",
    "def": "An overlapping 700–1200-token window of transcript turns, stripped of code/skills, stored as one vector+text doc."
  },
  "cohere": {
    "label": "Cohere",
    "def": "The ML provider used for embeddings (embed-v4.0) and reranking (rerank-v4.0-fast)."
  },
  "planetscale": {
    "label": "PlanetScale",
    "def": "The MySQL-compatible serverless database holding repos, checkpoints, hydration state, users, and API tokens."
  },
  "hyperdrive": {
    "label": "Hyperdrive",
    "def": "Cloudflare's connection pooler, used by Workers to query PlanetScale (Workers can't hold persistent DB connections)."
  },
  "cf-queue": {
    "label": "Cloudflare Queue",
    "def": "Cloudflare's message queue. The legacy search-index path enqueues checkpoint IDs for a consumer Worker; being retired in favor of NATS."
  },
  "r2": {
    "label": "R2",
    "def": "Cloudflare's S3-compatible object storage. Stripped transcripts are written here by the hydrator and read by the legacy CF indexer."
  },
  "trigram": {
    "label": "Trigram",
    "def": "A 3-byte substring. Peregrine indexes every overlapping trigram of (lowercased) file co

