package jwtverify

import "time"

// scopeOpenID is the scope an identity/jurisdiction token must carry — the
// shape only the jurisdiction-audience identity exchange produces (ADR
// 20260612).
const scopeOpenID = "openid"

// NewIdentityVerifier is a convenience constructor for the jurisdiction/
// identity-token contract (ADR 20260612): exact single audience plus
// scope=openid. It returns a plain *Verifier configured with WithExactAudience
// and WithRequiredScope — not a distinct type — so an identity-token relying
// party shares the exact same verification pipeline (and Verify contract)
// every other caller uses, just pre-configured for this one well-known
// shape. WithExactAudience (not WithAudiences) is deliberate: the ADR
// requires the audience to name precisely the jurisdiction host, and this
// contract has no downstream check that would catch a same-host token
// carrying a different scheme, port, or path the way host-only matching
// would wrongly admit.
//
// jurisdictionAudience must be non-empty — an empty value fails closed (no
// token's aud can match), the safe default for a service not yet told its
// jurisdiction.
func NewIdentityVerifier(jwksURL string, cacheTTL time.Duration, jurisdictionAudience string, opts ...Option) *Verifier {
	opts = append(opts, WithExactAudience(jurisdictionAudience), WithRequiredScope(scopeOpenID))
	return New(jwksURL, cacheTTL, opts...)
}
