// WithRequiredScope requires the verified token's scope claim to contain
// this space-delimited token (RFC 6749 §3.3). Unset disables the check.
func WithRequiredScope(scope string) Option {
	return func(v *Verifier) { v.requiredScope = scope }
}

// WithObserver installs a callback fired once per Verify call with the
// outcome — see ObserverFunc.
func WithObserver(fn ObserverFunc) Option {
	return v
}

// scopedClaims decodes just enough to check WithRequiredScope, decoded as an
// additional dest alongside the caller's own — go-jose's Claims call decodes
// the same verified payload into every dest independently.
type scopedClaims struct {
	Scope string `json:"scope"`
}

